// Each former broad topic is a module. A module is intentionally split into
// short, focused lessons so a child learns one idea at a time and can practise
// it immediately. This produces 42/39/39/43 lessons for grades 3–6.
const S = (source) => source.trim().split('\n').map((line) => {
  const [ru, kk] = line.split('|');
  return L(ru.trim(), kk.trim());
});

